mapper.select:
SELECT A.BILL_ID AS billId , A.BILL_TITLE AS billTitle , A.BILL_AMT AS billAmt , A.TAX_BILL_DT AS taxBillDt , A.IS_PAID AS isPaid , B.PROJ_NM AS projectName FROM TB_BILLING A LEFT JOIN TB_PROJECT B ON A.PROJ_ID = B.PROJ_ID WHERE 1=1
AND A.BILL_TITLE LIKE CONCAT('%', #{searchKeyword}, '%')
ORDER BY A.BILL_ID DESC LIMIT #{recordCountPerPage} OFFSET #{firstIndex}

mapper.insert:
INSERT INTO TB_BILLING (
    PROJ_ID, BILL_TITLE, BILL_AMT, TAX_BILL_DT, PAY_DT, IS_PAID, ACTUAL_PAY_DT, BILL_REMARK
) VALUES (
    #{projectId}, #{billTitle}, #{billAmt}, #{taxBillDt}, #{payDt}, #{isPaid}, #{actualPayDt}, #{billRemark}
)
